// Builds one envelope per counterparty from the mutual NDA template.
const TEMPLATE_URL = 'REPLACE_WITH_YOUR_TEMPLATE_URL'; // the stored mutual-nda template
const ACME = { name: 'Acme Corp', address: '100 Example Street, Springfield', signatory: 'Alex Chen', signatoryTitle: 'Head of Operations', email: 'alex.chen@example.com' };

return $input.all().map(({ json: row }) => ({
  json: {
    company: row.company,
    envelope: {
      title: `Mutual NDA: ${row.company}`,
      message: 'Please review and sign the mutual NDA.',
      routing: 'parallel', // both parties get it at once and sign in any order
      metadata: { counterparty: row.company },
      documents: [
        {
          key: 'nda',
          url: TEMPLATE_URL,
          format: 'docx',
          data: {
            effectiveDate: new Date().toISOString().slice(0, 10),
            partyA: { name: ACME.name, signatory: ACME.signatory, signatoryTitle: ACME.signatoryTitle, address: ACME.address },
            partyB: { name: row.company, address: row.address, signatory: row.signer_name },
            purpose: 'a possible business relationship',
            termYears: '2',
            survivalYears: '3',
            governingLaw: 'the State of Delaware',
          },
          places: [
            { key: 'party_a_signs_here', type: 'signature', recipient_key: 'party_a' },
            { key: 'party_b_signs_here', type: 'signature', recipient_key: 'party_b' },
          ],
        },
      ],
      recipients: [
        { type: 'signer', key: 'party_a', name: ACME.signatory, email: ACME.email },
        { type: 'signer', key: 'party_b', name: row.signer_name, email: row.signer_email },
      ],
    },
  },
}));
